code.java:
class Solution {
    public int findNumbers(int[] nums){
        int answer=0;
        for(int value:nums){
            int digits=0;
            for(int number=value;number>0;number/=10)digits++;
            if(digits%2==0)answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findNumbers(nums:IntArray):Int{
        var answer=0;
        for(value in nums){
            var number=value;
            var digits=0;
            while(number>0){
                digits++;
                number/=10
            };
            if(digits%2==0)answer++
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int findNumbers(vector<int>& nums){
        int answer=0;
        for(int value:nums){
            int digits=0;
            for(int number=value;number;number/=10)++digits;
            if(digits%2==0)++answer;
        }
